/** 详情态交易记录：机构/人员合一接口，服务端分页 */
async loadTransactionsIfNeeded(pageSize) {
  if (!['agency-detail', 'broker-detail'].includes(this.profileType) || this.showCreditRecords) {
    this.transactions = []
    this.transactionTotal = 0
    // 非交易记录态（分支机构/信用记录）必须复位加载态，否则切走后残留的 loading 会让骨架屏常驻
    this.transactionLoading = false
    return
  }
  // 交易记录归属 ID：机构用 companyId、人员用 personnelId；
  // 兼容仅有备案/记录 ID（*RecordId）的返回，避免取不到 ownerId 时不发请求也不置空导致骨架屏常驻
  const ownerId = this.profileType === 'agency-detail'
    ? this.profile.companyId || this.profile.companyRecordId
    : this.profile.personnelId || this.profile.personnelRecordId
  if (!ownerId) {
    this.transactions = []
    this.transactionTotal = 0
    this.transactionLoading = false
    return
  }
  const token = ++this.transactionToken
  this.transactionLoading = true
  // 骨架屏最多展示 TRANSACTION_SKELETON_MAX_WAIT：接口挂起（后端不可达/无日志响应）时
  // 到点即揭开骨架屏显示“暂无数据”，真实数据返回后再补填，避免用户长时间卡在骨架屏。
  const skeletonTimer = setTimeout(() => {
    if (token === this.transactionToken) this.transactionLoading = false
  }, TRANSACTION_SKELETON_MAX_WAIT)
  try {
    const res = await getPortalRecords({
      pageNum: this.transactionPage,
      pageSize: pageSize || this.pageSize,
      ownerType: this.profileType === 'agency-detail' ? 'agency' : 'staff',
      ownerId: String(ownerId)
    })
    if (token !== this.transactionToken) return
    // PageResult：rows/total 在顶层
    const rows = extractPageRows(res)
    this.transactionTotal = extractPageTotal(res, rows)
    this.transactions = rows
  } catch (error) {
    if (token !== this.transactionToken) return
    this.transactions = []
    this.transactionTotal = 0
  } finally {
    clearTimeout(skeletonTimer)
    if (token === this.transactionToken) this.transactionLoading = false
  }
},

