// 一次性验证脚本：模拟交易记录接口挂起，验证 3s 内骨架屏揭开（对应 bug：骨架屏一直转）
import { chromium } from '@playwright/test'

const BASE = process.env.VERIFY_BASE || 'http://localhost:8131'

// 让人物详情页有基本信息（否则页面走空），但 /broker/records 永不返回，模拟后端挂起
const DETAIL_STUB = {
  code: 200,
  data: { profileName: '王鹤棋', recordNo: 'SZJJ20261010002', personnelId: 'P-999', personnelRecordId: 'R-999', agencyName: '苏州恒一有限公司' }
}

const run = async () => {
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } })

  // 记录接口：永远不 fulfill（挂起），模拟后端不可达/无响应
  await page.route('**/portal/public/broker/records**', () => { /* hang */ })
  // 详情接口返回桩数据（带 personnelId，确保会发起交易记录请求）
  await page.route('**/portal/public/broker/staff/detail**', route =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(DETAIL_STUB) }))
  // 其它接口返回空壳
  await page.route('**/api/v3.0/**', route =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, rows: [], data: {}, total: 0 }) }))
  await page.route('**/api/v2.0/**', route =>
    route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ code: 200, rows: [], data: [], total: 0 }) }))

  // 通过路由带上 record 直达人员详情
  const record = encodeURIComponent(JSON.stringify({ personnelRecordId: 'R-999', personnelId: 'P-999', profileName: '王鹤棋', recordNo: 'SZJJ20261010002' }))
  await page.goto(`${BASE}/#/UnifiedLogin?portal=brokers&view=broker-detail&recordId=${record}`, { waitUntil: 'domcontentloaded' })

  // 等页面出现
  await page.waitForSelector('.public-portal-screen, .broker-pages', { timeout: 15000 }).catch(() => {})

  const skeletonSel = '.broker-transactions .portal-table-loading'
  const emptySel = '.broker-transactions .portal-table-empty'
  const start = Date.now()
  let cleared = false
  let sawSkeleton = false
  // 观察 6 秒
  while (Date.now() - start < 6000) {
    const sk = await page.locator(skeletonSel).count()
    const em = await page.locator(emptySel).count()
    if (sk > 0) sawSkeleton = true
    if (sk === 0) { cleared = true; console.log(`t=${Date.now() - start}ms skeleton=0 emptyVisible=${em > 0}`); break }
    await page.waitForTimeout(200)
  }
  const elapsed = Date.now() - start
  console.log(JSON.stringify({ sawSkeleton, cleared, elapsedMs: elapsed }))
  await browser.close()
  if (!cleared) { console.error('FAIL: 骨架屏未揭开'); process.exit(2) }
  console.log('PASS: 接口挂起时骨架屏在 ' + elapsed + 'ms 内揭开（上限 3000ms + 观察余量）')
}

run().catch(e => { console.error(e); process.exit(1) })

