  await page.waitForSelector('.portal-table tbody tr', { timeout: 25000 })
  await page.locator('.portal-table tbody tr').first().getByRole('button', { name: '基本信息', exact: true }).click()
  await page.waitForSelector('.broker-transactions', { timeout: 20000 })

  const skeletonSel = '.broker-transactions .portal-table-loading'
  const start = Date.now()
  let sawSkeleton = false
  let cleared = false
  let clearedAt = -1
  while (Date.now() - start < 8000) {
    const sk = await page.locator(skeletonSel).count()
    if (sk > 0) sawSkeleton = true
    if (sk === 0 && sawSkeleton) { cleared = true; clearedAt = Date.now() - start; break }
    await page.waitForTimeout(120)
  }
  const emptyVisible = await page.locator('.broker-transactions .portal-table-empty').count()
